import{ownerUserAvatar}from './owner-auth.js';
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
// Memory-only profile pictures. Existing owner endpoint verifies account, owner and MFA.
export function createStaffAvatarManager({load=ownerUserAvatar,isActive=()=>true,createUrl=blob=>URL.createObjectURL(blob),revokeUrl=url=>URL.revokeObjectURL(url),doc=document,clock=Date.now,interval=setInterval,clear=clearInterval,includeNode=()=>true}={}){
 let root=null,disposed=false,epoch=0;const cache=new Map(),pending=new Map(),urls=new Set();
 const active=()=>!disposed&&isActive()&&root?.isConnected;
 const nodes=id=>[...(root?.querySelectorAll('[data-member-avatar]')||[])].filter(el=>el.dataset.memberAvatar===id);
 function render(id,url){if(!active())return;for(const el of nodes(id)){let img=el.querySelector('img');if(!url){img?.remove();continue;}if(img?.getAttribute('src')===url)continue;if(!img){img=doc.createElement('img');img.alt='';img.decoding='async';img.onerror=()=>img.remove();el.append(img);}img.src=url;}}
 async function request(id){const cached=cache.get(id);if(cached&&cached.until>clock()){render(id,cached.url);return;}if(pending.has(id)){await pending.get(id);render(id,cache.get(id)?.url);return;}
  const generation=epoch;const job=(async()=>{let url=null;try{const blob=await load(id);if(!active()||generation!==epoch)return;if(blob?.type!=='image/jpeg'||blob.size<3||blob.size>200000)throw Error('No profile picture');const b=new Uint8Array(await blob.slice(0,3).arrayBuffer());if(b[0]!==255||b[1]!==216||b[2]!==255)throw Error('Invalid profile picture');if(!active()||generation!==epoch)return;url=createUrl(blob);urls.add(url);}catch{}if(!active()||generation!==epoch){if(url){urls.delete(url);revokeUrl(url);}return;}const old=cache.get(id)?.url;cache.set(id,{url,until:clock()+60000});render(id,url);while(cache.size>60){const victim=[...cache.keys()].find(key=>nodes(key).length===0)||cache.keys().next().value;const expired=cache.get(victim)?.url;cache.delete(victim);if(expired){urls.delete(expired);revokeUrl(expired);}}if(old&&old!==url){urls.delete(old);revokeUrl(old);}})();pending.set(id,job);try{await job;}finally{if(pending.get(id)===job)pending.delete(id);}
 }
 async function hydrate(scope){if(disposed)return;root=scope;if(!active())return;const ids=[...new Set([...root.querySelectorAll('[data-member-avatar]')].filter(includeNode).map(el=>el.dataset.memberAvatar).filter(id=>uuid.test(id||'')))];let cursor=0;await Promise.all(Array.from({length:Math.min(3,ids.length)},async()=>{while(cursor<ids.length&&active())await request(ids[cursor++]);}));}
 const refresh=()=>{if(active()&&!doc.hidden)void hydrate(root);};doc.addEventListener('visibilitychange',refresh);const timer=interval(refresh,60000);
 return{hydrate,dispose(){if(disposed)return;disposed=true;epoch++;clear(timer);doc.removeEventListener('visibilitychange',refresh);for(const url of urls)revokeUrl(url);urls.clear();cache.clear();pending.clear();root=null;}};
}
